args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  VALUES ?film1 { dbr:The_Brand_New_Testament }
  VALUES ?film2 { dbr:The_Boss_of_Rustler%27s_Roost }

  { { ?film1 dbo:country ?country1 } UNION { ?film1 dbp:country ?country1 } }
  { { ?film2 dbo:country ?country2 } UNION { ?film2 dbp:country ?country2 } }

  OPTIONAL { ?country1 rdfs:label ?label1 . FILTER(lang(?label1) = "" || langMatches(lang(?label1), "en")) }
  OPTIONAL { ?country2 rdfs:label ?label2 . FILTER(lang(?label2) = "" || langMatches(lang(?label2), "en")) }

  BIND( COALESCE(?label1, STR(?country1)) AS ?lab1 )
  BIND( COALESCE(?label2, STR(?country2)) AS ?lab2 )

  FILTER( LCASE(STR(?lab1)) = LCASE(STR(?lab2)) )
}

